// ========== Cart Management ==========
class Cart {
  constructor() {
    this.items = this.loadCart();
    this.cartButton = document.querySelector('[aria-label="View shopping cart"]');
    this.updateCartButton();
  }

  loadCart() {
    const stored = localStorage.getItem('cart');
    return stored ? JSON.parse(stored) : [];
  }

  saveCart() {
    localStorage.setItem('cart', JSON.stringify(this.items));
  }

  addItem(productName, price) {
    const existingItem = this.items.find((item) => item.name === productName);
    if (existingItem) {
      existingItem.quantity += 1;
    } else {
      this.items.push({ name: productName, price, quantity: 1 });
    }
    this.saveCart();
    this.updateCartButton();
    this.showNotification(`${productName} added to cart`);
  }

  getItemCount() {
    return this.items.reduce((sum, item) => sum + item.quantity, 0);
  }

  updateCartButton() {
    const count = this.getItemCount();
    if (count > 0) {
      this.cartButton.setAttribute('aria-label', `View shopping cart with ${count} items`);
    } else {
      this.cartButton.setAttribute('aria-label', 'View shopping cart');
    }
  }

  showNotification(message) {
    const notification = document.createElement('div');
    notification.setAttribute('role', 'status');
    notification.setAttribute('aria-live', 'polite');
    notification.className = 'notification';
    notification.textContent = message;
    document.body.appendChild(notification);

    setTimeout(() => {
      notification.classList.add('show');
    }, 10);

    setTimeout(() => {
      notification.classList.remove('show');
      setTimeout(() => notification.remove(), 300);
    }, 2500);
  }
}

// ========== Newsletter Subscription ==========
class Newsletter {
  constructor() {
    this.form = document.querySelector('.newsletter-form');
    if (this.form) {
      this.form.addEventListener('submit', (e) => this.handleSubmit(e));
    }
  }

  handleSubmit(e) {
    e.preventDefault();
    const input = this.form.querySelector('input[type="email"]');
    const email = input.value.trim();

    if (!email) {
      this.showError(input, 'Please enter a valid email');
      return;
    }

    if (!this.isValidEmail(email)) {
      this.showError(input, 'Please enter a valid email address');
      return;
    }

    this.clearError(input);
    this.saveSubscription(email);
  }

  isValidEmail(email) {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    return emailRegex.test(email);
  }

  saveSubscription(email) {
    localStorage.setItem('newsletter_email', email);
    const input = this.form.querySelector('input[type="email"]');
    const button = this.form.querySelector('button');
    const originalText = button.textContent;

    button.textContent = '✓ Subscribed!';
    input.value = '';

    setTimeout(() => {
      button.textContent = originalText;
    }, 2000);

    this.showNotification('Thank you for subscribing!');
  }

  showError(input, message) {
    input.setAttribute('aria-invalid', 'true');
    let errorElement = input.nextElementSibling;

    if (!errorElement || !errorElement.classList.contains('error-message')) {
      errorElement = document.createElement('div');
      errorElement.className = 'error-message';
      errorElement.setAttribute('role', 'alert');
      input.parentNode.insertBefore(errorElement, input.nextSibling);
    }

    errorElement.textContent = message;
    input.focus();
  }

  clearError(input) {
    input.setAttribute('aria-invalid', 'false');
    const errorElement = input.nextElementSibling;
    if (errorElement && errorElement.classList.contains('error-message')) {
      errorElement.remove();
    }
  }

  showNotification(message) {
    const notification = document.createElement('div');
    notification.setAttribute('role', 'status');
    notification.setAttribute('aria-live', 'polite');
    notification.className = 'notification';
    notification.textContent = message;
    document.body.appendChild(notification);

    setTimeout(() => {
      notification.classList.add('show');
    }, 10);

    setTimeout(() => {
      notification.classList.remove('show');
      setTimeout(() => notification.remove(), 300);
    }, 2500);
  }
}

// ========== Search Functionality ==========
class Search {
  constructor() {
    this.searchButton = document.querySelector('[aria-label="Search products"]');
    if (this.searchButton) {
      this.searchButton.addEventListener('click', () => this.openSearch());
    }
  }

  openSearch() {
    const query = prompt('Search StyleHub:', '');
    if (query && query.trim()) {
      this.showNotification(`Searching for: "${query}"`);
    }
  }

  showNotification(message) {
    const notification = document.createElement('div');
    notification.setAttribute('role', 'status');
    notification.setAttribute('aria-live', 'polite');
    notification.className = 'notification';
    notification.textContent = message;
    document.body.appendChild(notification);

    setTimeout(() => {
      notification.classList.add('show');
    }, 10);

    setTimeout(() => {
      notification.classList.remove('show');
      setTimeout(() => notification.remove(), 300);
    }, 2500);
  }
}

// ========== Product Interactions ==========
function initializeProductButtons() {
  const addToCartButtons = document.querySelectorAll('.btn-secondary');

  addToCartButtons.forEach((button) => {
    button.addEventListener('click', () => {
      const card = button.closest('.product-card');
      if (card) {
        const productName =
          card.querySelector('.product-name a')?.textContent || 'Product';
        const priceText = card.querySelector('.price-current')?.textContent || '$0.00';
        const price = parseFloat(priceText.replace('$', ''));

        cart.addItem(productName, price);
      }
    });
  });
}

// ========== Focus Management on Skip Link ==========
function initializeSkipLink() {
  const skipLink = document.querySelector('a[href="#maincontent"]');
  if (skipLink) {
    skipLink.addEventListener('click', (e) => {
      e.preventDefault();
      const mainContent = document.querySelector('#maincontent');
      if (mainContent) {
        mainContent.focus();
        mainContent.scrollIntoView({ behavior: 'smooth' });
      }
    });
  }
}

// ========== Notification Styles ==========
function initializeNotificationStyles() {
  if (!document.querySelector('style[data-notification]')) {
    const style = document.createElement('style');
    style.setAttribute('data-notification', 'true');
    style.textContent = `
      .notification {
        position: fixed;
        bottom: 2rem;
        left: 50%;
        transform: translateX(-50%) translateY(150px);
        background-color: #1a1a1a;
        color: white;
        padding: 1rem 1.5rem;
        border-radius: 6px;
        font-weight: 500;
        z-index: 1000;
        transition: transform 300ms ease-in-out;
        max-width: 90%;
        word-wrap: break-word;
      }

      .notification.show {
        transform: translateX(-50%) translateY(0);
      }

      .error-message {
        color: #ff6b6b;
        font-size: 0.875rem;
        margin-top: 0.5rem;
      }
    `;
    document.head.appendChild(style);
  }
}

// ========== Keyboard Navigation Enhancement ==========
function initializeKeyboardNavigation() {
  document.addEventListener('keydown', (e) => {
    // Close any open modals or search with Escape
    if (e.key === 'Escape') {
      e.preventDefault();
    }

    // Quick product filter with keyboard
    if ((e.ctrlKey || e.metaKey) && e.key === '/') {
      e.preventDefault();
      const search = new Search();
      search.openSearch();
    }
  });
}

// ========== Initialize App ==========
function initializeApp() {
  initializeNotificationStyles();

  // Create global cart instance
  window.cart = new Cart();

  // Initialize all features
  new Newsletter();
  new Search();
  initializeProductButtons();
  initializeSkipLink();
  initializeKeyboardNavigation();

  // Restore newsletter subscription if exists
  const savedEmail = localStorage.getItem('newsletter_email');
  if (savedEmail) {
    console.log(`User is subscribed: ${savedEmail}`);
  }
}

// ========== DOM Ready ==========
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', initializeApp);
} else {
  initializeApp();
}

